import{_ as e,o as t,c as r,a2 as n}from"./chunks/framework.BXzK3EA4.js";const o="/assets/jaianam1.CwAkNZGT.PNG",s="/assets/WhatsApp%20Image%202025-12-05%20at%2012.21.12%20PM.DSsCj9cS.jpeg",i="/assets/WhatsApp%20Image%202025-12-05%20at%2012.21.25%20PM.B__8Hd1R.jpeg",b=JSON.parse('{"title":"JainamXTS","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/jainamxts.md","filePath":"connect-brokers/brokers/jainamxts.md"}'),p={name:"connect-brokers/brokers/jainamxts.md"};function l(d,a,c,g,u,h){return t(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="jainamxts" tabindex="-1">JainamXTS <a class="header-anchor" href="#jainamxts" aria-label="Permalink to &quot;JainamXTS&quot;">​</a></h1><h3 id="jainam-xts-broker-integration" tabindex="-1"><strong>Jainam XTS Broker Integration</strong> <a class="header-anchor" href="#jainam-xts-broker-integration" aria-label="Permalink to &quot;**Jainam XTS Broker Integration**&quot;">​</a></h3><p>Tradeboard makes algorithmic trading accessible and straightforward by providing seamless integration with various brokers, including JainamXTS API. This documentation will guide you through the process of configuring your jainamxts account to work with Tradeboard</p><h4 id="step-1-create-api-applications" tabindex="-1"><strong>Step 1: Create API Applications</strong> <a class="header-anchor" href="#step-1-create-api-applications" aria-label="Permalink to &quot;**Step 1: Create API Applications**&quot;">​</a></h4><p>Login to <a href="https://jtrade.jainam.in:5000/dashboard#!/login" target="_blank" rel="noreferrer">https://jtrade.jainam.in:5000/dashboard#!/login</a></p><figure><img src="'+o+'" alt=""><figcaption></figcaption></figure><p>Once logged in:</p><ol><li>Go to <code>My App</code> &gt; <code>Create New Application</code></li><li>Create two separate apps:</li></ol><ul><li><strong>Interactive Order API</strong></li><li><strong>Market Data API</strong></li></ul><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><p><strong>Details to Fill:</strong></p><ul><li><strong>App Name</strong>: Tradeboard</li><li><strong>App Description</strong>: Tradeboard</li><li><strong>Redirect URL: (leave it empty)</strong></li><li><strong>Company Name</strong>: Tradeboard (or your own)</li><li>Choose the correct <strong>API Package</strong> depending on the app (Order or Market Data).</li></ul><figure><img src="'+i+`" alt=""><figcaption></figcaption></figure><p>Once submitted, wait for approval from the broker. After approval, the status will turn <strong>Active</strong>.</p><h4 id="step-2-setup-environment-variables" tabindex="-1">Step 2: Setup Environment Variables <a href="#step-2-setup-environment-variables" id="step-2-setup-environment-variables"></a> <a class="header-anchor" href="#step-2-setup-environment-variables" aria-label="Permalink to &quot;Step 2: Setup Environment Variables &lt;a href=&quot;#step-2-setup-environment-variables&quot; id=&quot;step-2-setup-environment-variables&quot;&gt;&lt;/a&gt;&quot;">​</a></h4><p>Refer to the <code>.sample.env</code> file in your Tradeboard folder and prepare your <code>.env</code> as follows:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Broker Configuration</span></span>
<span class="line"><span>BROKER_API_KEY = &#39;YOUR_BROKER_ORDER_API_KEY&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET = &#39;YOUR_ORDER_API_SECRET&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BROKER_API_KEY_MARKET = &#39;YOUR_BROKER_MARKET_API_KEY&#39;</span></span>
<span class="line"><span>BROKER_API_SECRET_MARKET = &#39;YOUR_BROKER_MARKET_API_SECRET&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>REDIRECT_URL = &#39;http://127.0.0.1:5000/jainamxts/callback&#39;</span></span></code></pre></div><p>Replace the values with actual credentials shown on your developer dashboard once approved.</p><h4 id="step-3-start-tradeboard" tabindex="-1"><strong>Step 3: Start Tradeboard</strong> <a class="header-anchor" href="#step-3-start-tradeboard" aria-label="Permalink to &quot;**Step 3: Start Tradeboard**&quot;">​</a></h4><p>Once all environment variables are set and your apps are <strong>Active</strong>, you can now start Tradeboard.</p><p>This completes the integration process for JainamXTS API with Tradeboard.</p><p>By following the steps outlined in this guide, you have successfully configured your JainamXTS API account for use with Tradeboard. You can now leverage the power of algorithmic trading to enhance your trading strategies and make data-driven decisions. Should you encounter any issues or need further assistance, please refer to the Tradeboard community or support resources. Happy trading!</p><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/jainamxts/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,25)])])}const _=e(p,[["render",l]]);export{b as __pageData,_ as default};
